import {
  ControlWrapper,
  ExtraContent,
  FormField,
  LabelGroup,
  LabelInstructionsWrapper,
} from "@components/form-controls/control.styles";
import FormInstructions from "@components/form-controls/instructions";
import FormLabel from "@components/form-controls/label";
import config, { Edition } from "@config/freeform/freeform.config";
import type { Message } from "@ff-client/types/properties";
import classes from "@ff-client/utils/classes";
import translate from "@ff-client/utils/translations";
import capitalize from "lodash/capitalize";
import type React from "react";
import type { PropsWithChildren } from "react";

import { useRenderContext } from "./context/render.context";
import { FormErrorList } from "./error-list";
import { FormMessageList } from "./message-list";

export type ControlProps = {
  edition?: Edition;
  label?: string;
  handle?: string;
  required?: boolean;
  instructions?: string;
  translatable?: boolean;
  hasTranslation?: boolean;
  isEncrypted?: boolean;
  removeTranslation?: () => void;
  width?: number;
  disabled?: boolean;
  errors?: string[];
  messages?: Message[];
  preContent?: React.ReactNode;
  extraContent?: React.ReactNode;
  align?: "start" | "center" | "end";
  justify?: "start" | "center" | "end";
};

export const ControlBlock: React.FC<PropsWithChildren<ControlProps>> = ({
  edition,
  label,
  handle,
  required,
  instructions,
  translatable,
  hasTranslation,
  removeTranslation,
  width,
  disabled,
  children,
  errors,
  messages,
  isEncrypted,
  preContent,
  extraContent,
  align,
  justify,
}) => {
  const { size } = useRenderContext();
  const {
    editions: { isAtLeast },
  } = config;
  const upsell =
    edition !== Edition.Express && !isAtLeast(edition || Edition.Express);

  return (
    <ControlWrapper
      className={classes(
        !!errors && "errors",
        disabled && "disabled",
        size && `size-${size}`,
        upsell && "upsell",
      )}
      data-upsell={translate("Upgrade to {edition} to unlock this setting.", {
        edition: capitalize(edition),
      })}
      $width={width}
    >
      <LabelGroup>
        {preContent !== undefined && <ExtraContent>{preContent}</ExtraContent>}

        <LabelInstructionsWrapper>
          <FormLabel
            label={label}
            handle={handle}
            required={required}
            translatable={translatable}
            hasTranslation={hasTranslation}
            isEncrypted={isEncrypted}
            removeTranslation={removeTranslation}
          />
          <FormInstructions instructions={instructions} />
        </LabelInstructionsWrapper>

        {extraContent !== undefined && (
          <ExtraContent>{extraContent}</ExtraContent>
        )}
      </LabelGroup>

      <FormField
        className={classes(
          align && `align-${align}`,
          justify && `justify-${justify}`,
        )}
      >
        {children}
      </FormField>

      <FormErrorList errors={errors} />
      <FormMessageList messages={messages} />
    </ControlWrapper>
  );
};
