import type { APIError } from "@ff-client/types/api";
import type React from "react";

type Props = {
  category: string;
  handle: string;
  error: APIError;
};

export const ApiErrorsBlock: React.FC<Props> = ({
  category,
  handle,
  error,
}) => {
  const list = error.errors?.[category]?.[handle] as string[];

  if (!list) {
    return null;
  }

  return (
    <ul className="errors">
      {list.map((error, idx) => (
        <li key={idx}>
          <span className="visually-hidden">Error:</span>
          {error}
        </li>
      ))}
    </ul>
  );
};
