import { Dropdown } from "@components/elements/custom-dropdown/dropdown";
import { TokenInput } from "@components/elements/token-input/token-input";
import { useFieldOptions } from "@components/options/use-field-options";
import type { Field } from "@editor/store/slices/layout/fields";
import type { FieldType } from "@ff-client/types/fields";
import type React from "react";

type Props = {
  field: Field;
  fieldType: FieldType;
  value: string;
  multiple?: boolean;
  onChange?: (value: string) => void;
};

export const GeneratedOptionsRuleValue: React.FC<Props> = ({
  field,
  fieldType,
  value,
  multiple,
  onChange,
}) => {
  const [options, loading] = useFieldOptions(field, fieldType);

  if (multiple) {
    let inputValue: string;
    if (value) {
      try {
        inputValue = JSON.parse(value);
      } catch {
        inputValue = value;
      }
    } else {
      inputValue = "";
    }

    return (
      <>
        {!loading && (
          <TokenInput
            value={inputValue}
            options={options
              .map((option) => {
                if ("value" in option) {
                  return {
                    value: option.value,
                    name: option.label,
                    editable: false,
                  };
                }

                return null;
              })
              .filter(Boolean)}
            allowCustom={false}
            onChange={(value) => onChange(JSON.stringify(value))}
          />
        )}
      </>
    );
  }

  return (
    <Dropdown
      emptyOption="Select an option"
      value={value}
      options={options}
      loading={loading}
      onChange={(selectedValue) => onChange?.(selectedValue)}
    />
  );
};
